{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.availability_master_v2 as ( with live_date_pre as ( SELECT LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group, MIN(PUBLISHEDAT::DATE) AS live_date, LOWER(status) AS status, legacyresourceid AS id, UPPER(title) AS product_name FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value GROUP BY 1, 3,4,5 ), sku_count as ( select sku_group, count(*) as status_count from live_date_pre group by 1 ), live_date_main as ( select upper(trim(a.sku_group)) as sku_group, a.status, a.id, a.product_name, live_date, row_number() over (partition by a.sku_group order by a.live_date desc) as rn, b.status_count from live_date_pre a left join sku_count b on a.sku_group = b.sku_group ), live_date_last_check as ( select sku_group, status, trim(id) as id, product_name, live_date from live_date_main where (status_count > 1 and rn = 2) or (status_count = 1 and rn = 1) ), first_order_date as ( select sku_group, min(order_timestamp::date) as first_order_date from snitch_db.maplemonk.fact_items_snitch group by 1 ), live_date_final_calculated as ( select a.sku_group, a.status, a.id, a.product_name, case when a.live_date is null and b.first_order_date is not null then b.first_order_date when b.first_order_date is null and a.live_date is not null then a.live_date else least(a.live_date,b.first_order_date) end as live_date from live_date_last_check a left join first_order_date b on a.sku_group = b.sku_group ), price2 as ( SELECT upper(trim(LEFT(VARIANT.value:sku::STRING, LENGTH(VARIANT.value:sku::STRING) - CHARINDEX(\'-\', REVERSE(VARIANT.value:sku::STRING))))) AS sku_group, VARIANT.value:compare_at_price::integer as cp_price, VARIANT.value:price::integer as price FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT ), final_price_pre as ( select distinct upper(trim(sku_group)) as sku_group, case when cp_price is null or cp_price = 0 then price else cp_price end as original_price, price as current_slashed_price from price2 ), final_price_adj as ( select sku_group, max(original_price) as original_price, max(current_slashed_price) as current_slashed_price from final_price_pre group by 1 ), price as ( select sku_group, case when current_slashed_price >= original_price then current_slashed_price else original_price end as original_price, current_slashed_price from final_price_adj ), category as ( SELECT trim(id) as id, producttype as category FROM ( SELECT SUBSTRING(id, POSITION(\'Product/\' IN id) + LENGTH(\'Product/\')) AS id, producttype, ROW_NUMBER() OVER (PARTITION BY SUBSTRING(id, POSITION(\'Product/\' IN id) + LENGTH(\'Product/\'))ORDER BY REPLACE(A.value:updated_at, \'\"\', \'\')DESC ) AS rw FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql , LATERAL FLATTEN (input => metafields) A ) WHERE rw = 1 ), live_date_final as ( select a.*, b.category from live_date_final_calculated a left join category b on a.id = b.id ), on_hold as ( select sku_group, size, sum(quantity) as quantiity from snitch_db.maplemonk.fact_items_snitch where tags like \'%eco-exchange-hold%\' and tags like \'%Snitch-RMS-Exchange for%\' and order_timestamp::date > current_date - 90 group by 1,2 ), snitch_final_inventory_wh2_pre as ( select trim(upper(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), CHARINDEX(\'-\', REVERSE(\"Item SkuCode\")) + 1, LEN(\"Item SkuCode\"))))) AS sku_group, REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\', REVERSE(\"Item SkuCode\")) - 1)) as size, sum(inventory) as inventory from snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date and facility in (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') GROUP BY 1,2 ), snitch_final_inventory_wh2 as ( select a.*, coalesce(b.quantiity,0) as hold_quantity, greatest(a.inventory-coalesce(b.quantiity,0),0) as final_quantity from snitch_final_inventory_wh2_pre a left join on_hold b on a.sku_group = b.sku_group and a.size = b.size ), pivot_table_pre as ( SELECT sku_group, sum(final_quantity) AS Sellable_Inventory, COALESCE(SUM(CASE WHEN size IN (\'4MSF\', \'4MAC\', \'SH01\', \'4MBL\', \'SH00\', \'BP00\', \'SN00\') THEN final_quantity ELSE 0 END), 0) AS NA_units, COALESCE(SUM(CASE WHEN size = \'XS\' OR size = \'28\' THEN final_quantity ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN size = \'S\' OR size = \'30\' THEN final_quantity ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN size = \'M\' OR size = \'32\' THEN final_quantity ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN size = \'L\' OR size = \'34\' THEN final_quantity ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN size = \'XL\' OR size = \'36\' THEN final_quantity ELSE 0 END), 0) AS XL_units, COALESCE(SUM(CASE WHEN size IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN final_quantity ELSE 0 END), 0) AS XXL_units, COALESCE(SUM(CASE WHEN size = \'3XL\' OR size = \'40\' THEN final_quantity ELSE 0 END), 0) AS XL3_units, COALESCE(SUM(CASE WHEN size = \'4XL\' OR size = \'42\' THEN final_quantity ELSE 0 END), 0) AS XL4_units, COALESCE(SUM(CASE WHEN size = \'5XL\' OR size = \'44\' THEN final_quantity ELSE 0 END), 0) AS XL5_units, COALESCE(SUM(CASE WHEN size = \'6XL\' OR size = \'46\' THEN final_quantity ELSE 0 END), 0) AS XL6_units, COALESCE(SUM(CASE WHEN size = \'7XL\' OR size = \'48\' THEN final_quantity ELSE 0 END), 0) AS XL7_units, COALESCE(SUM(CASE WHEN size = \'8XL\' OR size = \'50\' THEN final_quantity ELSE 0 END), 0) AS XL8_units FROM snitch_final_inventory_wh2 GROUP BY 1 ), PivotTable AS ( Select trim(upper(sku_group)) as sku_group, sum(Sellable_Inventory) as Sellable_Inventory, sum(XS_units) as XS_units, sum(S_units) as S_units, sum(M_units) as M_units, sum(L_units) as L_units, sum(XL_units) as XL_units, sum(XXL_units) as XXL_units, sum(XL3_units) as XL3_units, sum(XL4_units) as XL4_units, sum(XL5_units) as XL5_units, sum(XL6_units) as XL6_units, sum(XL7_units) as XL7_units, sum(XL8_units) as XL8_units, sum(NA_units) as NA_units from pivot_table_pre where lower(sku_group) not like\'cb%\' GROUP BY SKU_GROUP ), eoq_test_pre as ( select upper(trim(sku_group)) as sku_group, product_name, first_order_date, avg(final_ros) as final_ros, avg(eoq_new) as eoq_new, avg(total_units_on_hand) as total_units_on_hand, avg(op) as op, avg(natural_ros) as natural_ros, avg(sales_last_7_days) as sales_last_7_days, avg(sales_last_15_days) as sales_last_15_days, avg(sales_last_30_days) as sales_last_30_days from snitch_db.maplemonk.EOQ_Test where product_name is not null or product_name != \'\' group by 1,2,3 ) select coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group) as sku_group, product.id, price.original_price as price, price.current_slashed_price, product.product_name, case when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSS\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MST\' then \'T-Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSD\' then \'Jeans\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSW\' then \'Sweaters\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSO\' then \'Cargo Pants\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSK\' then \'Jackets\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MCR\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSR\' then \'Trousers\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),6) = \'4MBGSS\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),6) = \'4MBGSD\' then \'Jeans\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MTR\' then \'Cargo Pants\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSN\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),2) = \'SN\' then \'Sunglasses\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),2) = \'SH\' then \'Shoes\' else product.category end as category, EOQ_Test.final_ros, round(sum(coalesce(EOQ_Test.eoq_new,0)),0) as total_eoq, round(sum(coalesce(PivotTable.Sellable_Inventory,EOQ_Test.total_units_on_hand)),0) as available_units, round(sum(coalesce(EOQ_Test.op,0)),0) as order_point, EOQ_Test.natural_ros, EOQ_Test.sales_last_7_days, EOQ_Test.sales_last_15_days, EOQ_Test.sales_last_30_days, CASE WHEN EOQ_Test.final_ros >= 15 THEN \'1-Head\' WHEN EOQ_Test.final_ros < 15 AND EOQ_Test.final_ros >= 5 THEN \'2-Belly\' WHEN EOQ_Test.first_order_date > cast(getdate() as date)-45 THEN \'4-New\' WHEN EOQ_Test.first_order_date is not null and EOQ_Test.final_ros <5 then \'3-Tail\' WHEN EOQ_Test.first_order_date is null and product.status = \'active\' then \'4-New-Not-Sold\' WHEN EOQ_Test.first_order_date is null and product.status = \'draft\' then \'Draft\' WHEN product.status is null then \'Not-Cataloged\' ELSE \'Others\' END AS sku_class, PivotTable.Sellable_inventory, PivotTable.XS_units, PivotTable.S_units, PivotTable.M_units, PivotTable.L_units, PivotTable.XL_units, PivotTable.XXL_units, PivotTable.XL3_units, PivotTable.XL4_units, PivotTable.XL5_units, PivotTable.XL6_units, PivotTable.XL7_units, PivotTable.XL8_units, PivotTable.NA_units, (CASE WHEN PivotTable.XS_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.S_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XXL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL3_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL4_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL5_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL6_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL7_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL8_units > 0 THEN 1 ELSE 0 END) AS num_size_available, product.status, product.live_date from PivotTable full outer join eoq_test_pre as EOQ_Test on PivotTable.sku_group = EOQ_Test.sku_group left join live_date_final as product on coalesce(PivotTable.sku_group,EOQ_Test.sku_group) = product.sku_group left join price as price on coalesce(PivotTable.sku_group,EOQ_Test.sku_group) = price.sku_group where COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group) != \'TEST_SNITCH\' group by COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group), product.id, price.original_price, price.current_slashed_price, product.product_name, product.category, EOQ_Test.final_ros, EOQ_Test.natural_ros, EOQ_Test.sales_last_7_days, EOQ_Test.sales_last_15_days, EOQ_Test.sales_last_30_days, EOQ_Test.first_order_date, product.status, PivotTable.Sellable_inventory, PivotTable.XS_units, PivotTable.S_units, PivotTable.M_units, PivotTable.L_units, PivotTable.XL_units, PivotTable.XXL_units, PivotTable.XL3_units, PivotTable.XL4_units, PivotTable.XL5_units, PivotTable.XL6_units, PivotTable.XL7_units, PivotTable.XL8_units, PivotTable.NA_units, product.live_date )",
                    "transaction": true
                }
